  [1324106] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [1324187] = { "Trasforma il nemico in una pecora, costringendolo a vagare senza meta per un massimo di $D1. Mentre vaga, la pecora non può attaccare né lanciare incantesimi, ma rigenera molto rapidamente. Eventuali danni riportano il bersaglio alla sua forma originaria. Si può metamorfosare un solo bersaglio alla volta. Funziona solo su bestie, umanoidi e animali.", "Impossibile attaccare o lanciare incantesimi. Rigenerazione aumentata.", 0xd637006c, 0x445227a4, "uu" },
