  [1324422] = { "Incatena il bersaglio nemico non morto per un massimo di $D1. L'unità incatenata non può muoversi, attaccare o lanciare incantesimi. Eventuali danni inflitti liberano il bersaglio. Può essere incatenato solo un bersaglio alla volta.", "Incatenato.", 0xd5f2a9c8, 0x440dd100, "uu" },
