  [1324448] = { "Incute paura al nemico, costringendolo a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventato solo $N2 bersaglio alla volta.", "Impaurito.", 0xe2e8be41, 0xa91fab04, "uu" },
