  [1324459] = { "Fa fuggire in preda all'orrore il nemico bersaglio per $D1 e gli infligge $N2 danni da ombra. L'incantatore guadagna in salute il $N3% dei danni inflitti.", "Terrorizzato.", 0xe30b0be3, 0xa941f8a6, "uu" },
  [1324462] = { "Esilia il nemico bersaglio, impedendogli di compiere qualsiasi azione ma rendendolo invulnerabile per un massimo di $D1. Può essere esiliato solo un bersaglio alla volta. Funziona solo su demoni ed elementali.", "Invulnerabile, ma impossibilitato ad agire.", 0x59ac4db2, 0xe2069da9, "uu" },
  [1324463] = { "Esilia il nemico bersaglio, impedendogli di compiere qualsiasi azione ma rendendolo invulnerabile per un massimo di $D1. Può essere esiliato solo un bersaglio alla volta. Funziona solo su demoni ed elementali.", "Invulnerabile, ma impossibilitato ad agire.", 0xd7044d04, 0x451f743c, "uu" },
  [1324468] = { "Soggioga il demone bersaglio, fino al livello $N1, costringendolo a eseguire i tuoi ordini. Mentre è soggiogato, l'intervallo tra gli attacchi del demone aumenta del $N2% e la sua velocità di lancio d'incantesimi si riduce del $N3%. Dura fino a $D1. Se soggioghi ripetutamente lo stesso demone, diventerà più difficile da controllare a ogni tentativo.", "Assoggettato.", 0xe25db31f, 0xa8949fe2, "uu" },
  [1324474] = { "Mossa risolutiva che stordisce il bersaglio. La durata aumenta con i punti combo:\n $N1 punto: $N2 s\n $N3 punti: $N4 s\n $N5 punti: $N6 s\n $N7 punti: $N8 s\n $N9 punti: $N10 s", { "Stordito e danni subiti dal Ladro aumentati del $N1%.", "Stordito.", shape = { "1/0", "0/0" } }, 0x59ab841c, 0xe205d413, "uu" },
  [1324475] = { "Mossa risolutiva che stordisce il bersaglio. La durata aumenta con i punti combo:\n $N1 punto: $N2 s\n $N3 punti: $N4 s\n $N5 punti: $N6 s\n $N7 punti: $N8 s\n $N9 punti: $N10 s", { "Stordito e danni subiti dal Ladro aumentati del $N1%.", "Stordito.", shape = { "1/0", "0/0" } }, 0xe34f61fe, 0xa9864ec1, "uu" },
  [1324477] = { "Acceca il bersaglio, costringendolo a vagare disorientato per un massimo di $D1. Eventuali danni inflitti interrompono l'effetto.", "Disorientato.", 0xe28000b6, 0xa8b6ed79, "uu" },
